from typing import List

class Solution:
    def goodDaysToRobBank(self, security: List[int], time: int) -> List[int]:
        n = len(security)
        res = []
        for i in range(time, n - time):
            ok = all(security[j] >= security[j + 1] for j in range(i - time, i))
            ok = ok and all(security[j] <= security[j + 1] for j in range(i, i + time))
            if ok:
                res.append(i)
        return res

