            bool ok = true;
            for (int j = i - time; j < i && ok; ++j)
                ok = security[j] >= security[j + 1];
            for (int j = i; j < i + time && ok; ++j)
                ok = security[j] <= security[j + 1];
            if (ok) res.push_back(i);
        }
        return res;
    }
};

