        vector<int> nonInc(n, 0), nonDec(n, 0), res;
        for (int i = 1; i < n; ++i)
            nonInc[i] = security[i - 1] >= security[i] ? nonInc[i - 1] + 1 : 0;
        for (int i = n - 2; i >= 0; --i)
            nonDec[i] = security[i] <= security[i + 1] ? nonDec[i + 1] + 1 : 0;
        for (int i = 0; i < n; ++i)
            if (nonInc[i] >= time && nonDec[i] >= time) res.push_back(i);
        return res;
    }
};

